from scipy.optimize import least_squares
y=dP_dt
def nm(r): return np.sum(r**2)/np.sum((y-y.mean())**2)
forms={
'A: -P(a+bP)(1-exp(-ct))': lambda p: -P*(p[0]+p[1]*P)*(1-np.exp(-p[2]*t))+p[3],
'B: -a P/(1+bP) * (1-exp(-ct))': lambda p: -p[0]*P/(1+p[1]*P)*(1-np.exp(-p[2]*t))+p[3],
'C: -P*(a+b t^c)/(1+dP)': lambda p: -P*(p[0]+p[1]*t**p[2])/(1+p[3]*P),
'D: -a P/(1+bP+c t)': lambda p: -p[0]*P/(1+p[1]*P+p[2]*t),
'E: -a P^p (1-exp(-ct))': lambda p: -p[0]*P**p[1]*(1-np.exp(-p[2]*t))+p[3]*t,
'F: -P(a+bt)exp(-cP)': lambda p: -P*(p[0]+p[1]*t)*np.exp(-p[2]*P/(1+t))+p[3],
}
for k,f in forms.items():
    bestr=None
    for s in range(12):
        p0=np.random.RandomState(s).uniform(0.1,2,4)
        try:
            r=least_squares(lambda p: f(p)-y,p0,max_nfev=3000)
            if bestr is None or r.cost<bestr.cost: bestr=r
        except Exception as e: pass
    print(k, nm(bestr.fun), np.round(bestr.x,4))

